def find_base_blocks():
    from itertools import combinations

    # All possible base blocks containing 0
    base_blocks = []
    for b in combinations(range(1, 13), 2):
        block = (0, b[0], b[1])
        diffs = [0]*13
        for i in range(3):
            for j in range(3):
                if i != j:
                    diffs[(block[i] - block[j]) % 13] += 1
        base_blocks.append((block, diffs))

    # We need to choose 8 base blocks such that the sum of diffs is 4 for each non-zero element
    # Let's use a simple backtracking

    def search(idx, current_diffs, selected):
        if len(selected) == 8:
            if all(d == 4 for d in current_diffs[1:]):
                return selected
            return None

        if idx >= len(base_blocks):
            return None

        # Try without this block
        res = search(idx + 1, current_diffs, selected)
        if res: return res

        # Try with this block
        block, diffs = base_blocks[idx]
        new_diffs = current_diffs[:]
        valid = True
        for i in range(1, 13):
            new_diffs[i] += diffs[i]
            if new_diffs[i] > 4:
                valid = False
                break

        if valid:
            res = search(idx, new_diffs, selected + [block]) # Can we repeat base blocks? Yes, BIBD can have repeated blocks.
            if res: return res

        return None

    res = search(0, [0]*13, [])
    print("Base blocks:", res)

find_base_blocks()

